import java.io.*;import java.nio.charset.StandardCharsets;import java.security.*;import java.util.*;import catdata.*;import catdata.cql.*;import catdata.cql.exp.*;import org.json.*;
/** One resident process, one serial request, fresh official environment each time. */
public final class CqlWorker {
 static final JSONObject CAP=new JSONObject().put("protocol","cql-worker/v1").put("operations",new JSONArray(List.of("health","schema_validate","draft","validate","evaluate","evaluate_recipe"))).put("scalarTypes",new JSONArray(List.of("Text","Integer","exactReal","Bool"))).put("querySubset","typed paths/conversions; FROM/WHERE; branch unions and key quotients").put("schemaEquations","native unary paths; constants unsupported").put("populationPlans",true).put("scalarConversions",new JSONArray(ScalarFunctions.TARGETS.keySet())).put("dataEvaluation",true).put("arbitraryCql",false).put("sqlExecution",false).put("nullSemantics","null input explicitly unsupported; nullable metadata preserved").put("bundledRecipes",SealedPlanRegistry.ids()).put("recipeSourceBindings","explicit physical source cells; hidden PK business role may be bound as recipe input").put("keySemantics","primary/unique keys preserved as metadata; uniqueness not asserted by CQL");
 static void evaluate(String text)throws Exception{Program<Exp<?>> p=AqlParserFactory.getParser().parseProgram(text);AqlEnv env=new AqlEnv(p);env.typing=new AqlTyping(p,false);for(String n:p.order){Exp<?> e=p.exps.get(n);if(!Set.of(Kind.TYPESIDE,Kind.SCHEMA,Kind.QUERY,Kind.MAPPING,Kind.CONSTRAINTS).contains(e.kind()))throw new IllegalArgumentException("Prohibited expression");env.defs.put(n,e.kind(),e.eval(env,false));}}
 static String digest(String x)throws Exception{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(x.getBytes(StandardCharsets.UTF_8)));}
 static JSONObject run(String op,JSONObject p)throws Exception{JSONObject out=new JSONObject().put("capabilities",CAP).put("diagnostics",new JSONArray());if(op.equals("health"))return out.put("status","ready");String program="";try{if(op.equals("evaluate_recipe"))return SealedPlanRunner.run(p).put("capabilities",CAP);if(op.equals("schema_validate")){SchemaCompiler s=new SchemaCompiler(p.getJSONObject("schema"),"S");program=SchemaCompiler.TYPES+s.program();out.put("manifest",s.manifest());evaluate(program);out.put("status","valid");}else if(op.equals("draft")||op.equals("validate")||op.equals("evaluate")){SchemaCompiler s=new SchemaCompiler(p.getJSONObject("source"),"S"),t=new SchemaCompiler(p.getJSONObject("target"),"T");program=SchemaCompiler.TYPES+s.program()+t.program();evaluate(program);JSONArray assignments=p.optJSONArray("assignments",p.optJSONObject("recipe",new JSONObject()).optJSONArray("assignments",new JSONArray()));PopulationCompiler population=PopulationCompiler.applies(assignments)?new PopulationCompiler(s,t,assignments):null;QueryCompiler q=population==null?new QueryCompiler(s,t,assignments):null;
JSONArray holes=population==null?q.holes:population.holes;out.put("manifest",new JSONObject().put("source",s.manifest()).put("target",t.manifest())).put("holes",holes).put("assignments",assignments);
if(population==null){String query=q.program();program=SchemaCompiler.types(q.conversionsUsed)+s.program()+t.program()+query;}else program=population.definitions();boolean complete=population==null?q.complete():population.complete();
if(!complete)out.put("status","incomplete");else{evaluate(program);out.put("status","valid");if(op.equals("evaluate")){DataEvaluator.requireTargetKeyTransport(t);long started=System.nanoTime();DataEvaluator d=new DataEvaluator(s,t,p.getJSONObject("data"));program+=population==null?d.instance():population.instances(d);AqlEnv env=population==null?DataEvaluator.evaluate(program):population.evaluate(program);out.put("tables",d.result((Instance)env.get(Kind.INSTANCE,"Result"))).put("inputIdentities",d.identityManifest).put("targetSchema",t.nativeSpec).put("status","evaluated").put("timing",new JSONObject().put("evaluationMs",(System.nanoTime()-started)/1e6));}}
}else throw new UnsupportedOperationException("Unknown operation: "+op);}catch(UnsupportedOperationException ex){out.put("status","inconclusive").getJSONArray("diagnostics").put(new JSONObject().put("code","unsupported").put("message",ex.getMessage()));}catch(Exception ex){out.put("status","invalid").getJSONArray("diagnostics").put(new JSONObject().put("code","cql_validation_failed").put("message",ex.toString()));}for(String key:List.of("targetHash","baseRevision","sourceDataDigest"))if(p.has(key))out.put(key,p.get(key));return out.put("program",program).put("programSha256",digest(program));}
 public static void main(String[] args)throws Exception{PrintStream wire=System.out;System.setOut(System.err);BufferedReader reader=new BufferedReader(new InputStreamReader(System.in,StandardCharsets.UTF_8));String line;while((line=reader.readLine())!=null){JSONObject r=new JSONObject();try{JSONObject request=new JSONObject(line);r.put("id",request.opt("id")).put("ok",true).put("result",run(request.getString("op"),request.optJSONObject("payload",new JSONObject())));}catch(Throwable ex){r.put("ok",false).put("error",new JSONObject().put("code","invalid_request").put("message",ex.toString()));}wire.println(r.toString());wire.flush();}}
}
